    [3079]={name="Skorn's Rifle",quality=2,ilvl=12,sourceType="quest_reward",instructions="Reward from the quest 'The Demon Scarred Cloak' - pick it over the other choices. In Mulgore.",zone="Mulgore",questName="The Demon Scarred Cloak",lore="The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Bloodhoof Village should know of Ghost Howl's demise...."},
