    [6070]={name="Wolfskin Bracers",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Wolves Across the Border' - pick it over the other choices. In Northshire Valley.",zone="Northshire Valley",questName="Wolves Across the Border",lore="I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful."},
