    [6720]={name="Spirit Hunter Headdress",quality=2,ilvl=37,sourceType="quest_reward",instructions="Reward from the quest 'Frostmaw'. In Thunder Bluff.",zone="Thunder Bluff",questName="Frostmaw",lore="it is now time for you to travel to far-off lands. You are ready. You now hunt Frostmaw, a yeti in the Alterac Mountains. He is elusive, his white coat blending into the snows of his mountain home."},
    [6723]={name="Medal of Courage",quality=3,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Saving Yenniku' - pick it over the other choices. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Saving Yenniku",lore="I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."},
    [6748]={name="Monkey Ring",quality=2,ilvl=31,sourceType="quest_reward",instructions="Reward from the quest 'Willix the Importer' - pick it over the other choices. In Razorfen Kraul.",zone="Razorfen Kraul",questName="Willix the Importer",lore="At last, help has arrived! You have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place."},
