    [16886]={name="Outlaw Sabre",quality=3,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Baron Aquanis' - pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Baron Aquanis",lore="The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."},
    [16905]={name="Bloodfang Chestpiece",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [16910]={name="Bloodfang Belt",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Vaelastrasz the Corrupt in Blackwing Lair.",zone="Blackwing Lair",npc="Vaelastrasz the Corrupt",lore="A red dragon of Alexstrasza's flight, broken by Nefarian's experiments. He asks to be killed before the corruption finishes taking him, and apologises while he fights."},
    [16911]={name="Bloodfang Bracers",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Razorgore the Untamed in Blackwing Lair.",zone="Blackwing Lair",npc="Razorgore the Untamed",lore="Set to guard the stolen dragon eggs. The raid takes control of the orb he is chained to and turns him on the clutch he was protecting."},
