    [17054]={name="Joonho's Mercy",quality=3,ilvl=50,reqLevel=45,sourceType="world_drop",instructions="Drops from General Fangferror (rare spawn) in Kalimdor.",zone="Kalimdor",npc="General Fangferror",proc="Chance on hit: Blasts a target for 70 Arcane damage."},
    [17063]={name="Band of Accuria",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."},
    [17069]={name="Striker's Mark",quality=4,ilvl=69,reqLevel=60,sourceType="boss_drop",instructions="Drops from Magmadar in Molten Core.",zone="Molten Core",npc="Magmadar",lore="A core hound of the deep fire, kept as a guard beast and fed by Ragnaros's lieutenants."},
    [17694]={name="Band of the Fist",quality=2,ilvl=25,sourceType="quest_reward",instructions="Reward from the quest 'Allegiance to the Old Gods' - pick it over the other choices. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Allegiance to the Old Gods",lore="This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."},
