    [17710]={name="Charstone Dirk",quality=3,ilvl=54,reqLevel=48,sourceType="boss_drop",instructions="Drops from Princess Theradras in Maraudon.",zone="Maraudon",npc="Princess Theradras",lore="A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."},
