    [19127]={name="Charred Leather Tunic",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Overseer Maltorius' - pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="WANTED: Overseer Maltorius",lore="By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed."},
    [19159]={name="Woven Ivy Necklace",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: Vile Priestess Hexx and Her Minions' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Wanted: Vile Priestess Hexx and Her Minions",lore="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."},
    [19352]={name="Chromatically Tempered Sword",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Chromaggus in Blackwing Lair.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's chromatic experiment, made into a sword. It carries the blood of every dragonflight and none of their loyalty."},
    [19377]={name="Prestor's Talisman of Connivery",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
