    [21126]={name="Death's Sting",quality=4,ilvl=84,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21278]={name="Stormshroud Gloves",quality=3,ilvl=55,reqLevel=50,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [21359]={name="Deathdealer's Boots",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Deathdealer's Boots'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Deathdealer's Boots",lore="The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you."},
    [21360]={name="Deathdealer's Helm",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Deathdealer's Helm'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Deathdealer's Helm",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21361]={name="Deathdealer's Spaulders",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Deathdealer's Spaulders'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Deathdealer's Spaulders",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21364]={name="Deathdealer's Vest",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Deathdealer's Vest'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Deathdealer's Vest",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21459]={name="Crossbow of Imminent Doom",quality=4,ilvl=72,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ossirian the Unscarred in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Ossirian the Unscarred",lore="A qiraji lieutenant holding the Ruins, whose name stopped being accurate the first time a raid used the crystals against him."},
    [21567]={name="Rune of Duty",quality=3,ilvl=45,reqLevel=40,sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp - costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
