    [21586]={name="Belt of Never-ending Agony",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21602]={name="Qiraji Execution Bracers",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21664]={name="Barbed Choker",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Fankriss the Unyielding in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Fankriss the Unyielding",lore="A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."},
    [21672]={name="Gloves of Enforcement",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Battleguard Sartura in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Battleguard Sartura",lore="The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."},
    [21701]={name="Cloak of Concentrated Hatred",quality=4,ilvl=73,reqLevel=60,sourceType="boss_drop",instructions="Drops from The Prophet Skeram in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="The Prophet Skeram",lore="C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."},
    [21710]={name="Cloak of the Fallen God",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Savior of Kalimdor' - pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="The Savior of Kalimdor",lore="To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."},
    [21809]={name="Fury of the Forgotten Swarm",quality=3,ilvl=71,reqLevel=60,sourceType="boss_drop",instructions="Drops from Colonel Zerran in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Colonel Zerran"},
    [22003]={name="Darkmantle Boots",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Anthion's Parting Words'. In Ironforge.",zone="Ironforge",questName="Anthion's Parting Words",lore="Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."},
    [22005]={name="Darkmantle Cap",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22006]={name="Darkmantle Gloves",quality=4,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Just Compensation'. In Ironforge.",zone="Ironforge",questName="Just Compensation",lore="I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gloves that you wish to upgrade."},
    [22009]={name="Darkmantle Tunic",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22150]={name="Beads of Ogre Might",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'Falrin's Vendetta' - pick it over the other choices. In Dire Maul.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
